import { expect, test } from '@playwright/test'

/**
 * Visual regression for the marketing home (#1913).
 *
 * The committed baselines MUST be generated by CI, never a dev machine — font
 * rasterization and GPU output differ between platforms, so a macOS-captured
 * baseline can never pass the linux runner. `.github/workflows/visual-baselines.yml`
 * regenerates them (workflow_dispatch, `--update-snapshots`) and uploads them as
 * an artifact to commit.
 *
 * The assertion is skipped unless `VISUAL_BASELINES` is set, which the baseline
 * job and the regular E2E run control — see the workflow.
 */
test.use({ colorScheme: 'dark' })

test('home matches the committed baseline', async ({ page }, testInfo) => {
  test.skip(!process.env.VISUAL_BASELINES, 'baselines run in the dedicated CI job')
  await page.goto('/')
  await page.evaluate(() => document.fonts.ready)
  await page.waitForTimeout(1000)

  await expect(page).toHaveScreenshot(`${testInfo.project.name}-home.png`, {
    fullPage: true,
    animations: 'disabled',
    maxDiffPixelRatio: 0.02,
  })
})
